SELECT  FROM note
WHERE workspace_id = #{workspaceId}
  AND person_id IN
  #{personId}
ORDER BY created_at DESC, id DESC

SELECT 
FROM note n
LEFT JOIN app_user u ON u.id = n.author_id
LEFT JOIN person   p ON p.id = n.person_id
LEFT JOIN deal     d ON d.id = n.deal_id
WHERE n.workspace_id = #{workspaceId}
  AND (n.content LIKE #{query}
  OR n.title LIKE #{query}
  OR u.display_name LIKE #{query}
  OR u.username LIKE #{query}
  OR p.name LIKE #{query}
  OR d.name LIKE #{query})
ORDER BY n.created_at DESC, n.id DESC
LIMIT 10

SELECT  FROM note
WHERE workspace_id = #{workspaceId}
  AND (visibility = 'workspace' OR author_id = #{currentUserId})
ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM note
WHERE workspace_id = #{workspaceId}
  AND (visibility = 'workspace' OR author_id = #{currentUserId})

SELECT id FROM note
WHERE workspace_id = #{workspaceId}
  AND id IN #{noteId}
  AND (visibility = 'workspace' OR author_id = #{currentUserId})

SELECT  FROM note
WHERE workspace_id = #{workspaceId} AND id = #{id}
  AND (visibility = 'workspace' OR author_id = #{currentUserId})

SELECT 
FROM note n
LEFT JOIN app_user u ON u.id = n.author_id
LEFT JOIN person   p ON p.id = n.person_id
LEFT JOIN deal     d ON d.id = n.deal_id
WHERE n.workspace_id = #{workspaceId}
  AND (n.visibility = 'workspace' OR n.author_id = #{currentUserId})
  AND (n.content LIKE #{query}
  OR n.title LIKE #{query}
  OR u.display_name LIKE #{query}
  OR u.username LIKE #{query}
  OR p.name LIKE #{query}
  OR d.name LIKE #{query})
ORDER BY n.created_at DESC, n.id DESC
LIMIT 10
